public int minCostClimbingStairs(int[] cost) {
    if (cost.length < 1) return 0;
    if (cost.length == 1) return cost[0];
    int first = cost[0];
    int second = cost[1];
    for (int i = 2; i < cost.length; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
        second = current;
    }
    return Math.min(first, second);
}

