    List<Integer> fibs = new ArrayList<>();
    int n = 0;
    while (n * n <= k) {
        fibs.add(n * n);
        n++;
    }
    Collections.reverse(fibs);
    int count = 0;
    for (int fib : fibs) {
        while (k >= fib) {
            k -= fib;
            count++;
        }
        if (k == 0) {
            return count;
        }
    }
    return -1;
}

